"""Command line interface for receipt summaries."""

import csv
import json
import os
import sys
import tempfile

from .model import summarize

__all__ = ["main"]

_USAGE = "usage: python -m receipt_tools.cli INPUT.jsonl OUTPUT.csv"


def _load(path):
    records = []
    with open(path, "r", encoding="utf-8") as handle:
        for line in handle:
            if not line.strip():
                continue
            try:
                records.append(json.loads(line))
            except json.JSONDecodeError as exc:
                raise ValueError("malformed JSON line") from exc
    return records


def _write(path, rows):
    directory = os.path.dirname(os.path.abspath(path))
    handle, temp_path = tempfile.mkstemp(
        prefix=".receipt-", suffix=".tmp", dir=directory
    )
    try:
        with os.fdopen(handle, "w", encoding="utf-8", newline="") as out:
            writer = csv.writer(out, lineterminator="\n")
            writer.writerow(["customer", "count", "total"])
            for row in rows:
                writer.writerow([row["customer"], row["count"], row["total"]])
        os.replace(temp_path, path)
    except BaseException:
        try:
            os.unlink(temp_path)
        except OSError:
            pass
        raise


def main(argv=None):
    args = list(sys.argv[1:] if argv is None else argv)
    if len(args) != 2:
        print(_USAGE, file=sys.stderr)
        return 2
    source, destination = args
    try:
        rows = summarize(_load(source))
        _write(destination, rows)
    except (OSError, ValueError) as exc:
        print("error: {}".format(exc), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Validation and summary of receipt records."""

import re
from decimal import Decimal, ROUND_HALF_UP, localcontext

__all__ = ["summarize"]

_AMOUNT_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?", re.ASCII)
_CENTS = Decimal("0.01")
_PRECISION = 60
_STATUSES = ("paid", "void")


def _customer(record):
    value = record.get("customer")
    if not isinstance(value, str):
        raise ValueError("customer must be a string")
    name = value.strip()
    if not name:
        raise ValueError("customer must not be empty")
    return name


def _amount(record):
    value = record.get("amount")
    if not isinstance(value, str) or _AMOUNT_RE.fullmatch(value) is None:
        raise ValueError("amount must be a decimal string")
    return Decimal(value)


def _status(record):
    value = record.get("status")
    if not isinstance(value, str) or value not in _STATUSES:
        raise ValueError('status must be "paid" or "void"')
    return value


def summarize(records):
    """Return per-customer paid receipt counts and rounded totals."""
    totals = {}
    with localcontext() as ctx:
        ctx.prec = _PRECISION
        for record in records:
            if not isinstance(record, dict):
                raise ValueError("receipt must be a mapping")
            name = _customer(record)
            amount = _amount(record)
            status = _status(record)
            if status != "paid":
                continue
            entry = totals.get(name)
            if entry is None:
                totals[name] = [1, amount]
            else:
                entry[0] += 1
                entry[1] += amount

        summary = []
        for name in sorted(totals):
            count, total = totals[name]
            rounded = total.quantize(_CENTS, rounding=ROUND_HALF_UP)
            summary.append({"customer": name, "count": count, "total": str(rounded)})
    return summary

