import pricing

CENT = Decimal('0.01')


def format_amount(value):
    """Format an amount as a 0.00 string, tolerating non-Decimal replacements."""
    if not isinstance(value, Decimal):
        value = Decimal(str(value))
    return str(value.quantize(CENT, rounding=ROUND_HALF_UP))


def quote(items, tier='bronze'):
    lines = []
    total = Decimal('0.00')
    for item in items:
        amount = pricing.price_line(item['unit_price'], item['quantity'], tier)
        total += amount if isinstance(amount, Decimal) else Decimal(str(amount))
        lines.append({'sku': item['sku'], 'amount': format_amount(amount)})
    return {'lines': lines, 'total': format_amount(total)}

"""Single owner of the pricing formula shared by checkout and reporting."""

import re
from decimal import Decimal, ROUND_HALF_UP, localcontext

CENT = Decimal('0.01')
BULK_THRESHOLD = 10
BULK_MULTIPLIER = Decimal('0.95')

TIER_MULTIPLIERS = {
    'bronze': Decimal('1'),
    'silver': Decimal('0.90'),
    'gold': Decimal('0.80'),
}

_MONEY_RE = re.compile(r'[0-9]+(?:\.[0-9]+)?')


def _money(value):
    if not isinstance(value, str) or _MONEY_RE.fullmatch(value) is None:
        raise ValueError('unit_price must be an ASCII nonnegative decimal string')
    return Decimal(value)


def _quantity(value):
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError('quantity must be a nonnegative int')
    return value


def _tier(value):
    if not isinstance(value, str) or value not in TIER_MULTIPLIERS:
        raise ValueError("tier must be 'bronze', 'silver' or 'gold'")
    return TIER_MULTIPLIERS[value]


def price_line(unit_price, quantity, tier='bronze'):
    """Return the exact line amount quantized to 0.01 with ROUND_HALF_UP."""
    price = _money(unit_price)
    qty = _quantity(quantity)
    multiplier = _tier(tier)
    with localcontext() as ctx:
        ctx.prec = 60
        amount = price * qty * multiplier
        if qty >= BULK_THRESHOLD:
            amount = amount * BULK_MULTIPLIER
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)

