"""Command-line JSON Lines to CSV receipt summary converter."""

from __future__ import annotations

import csv
import io
import json
import os
import sys
import tempfile
from collections.abc import Sequence
from typing import Any

from .model import summarize


def _read_summary(path: str) -> list[dict[str, Any]]:
    """Read all receipts from a UTF-8 JSON Lines file and validate them."""
    records: list[Any] = []
    with open(path, "r", encoding="utf-8", newline="") as source:
        for line_number, line in enumerate(source, 1):
            if not line.strip():
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError as exc:
                raise ValueError(
                    f"malformed JSON on line {line_number}: {exc.msg}"
                ) from exc
            records.append(record)
    # summarize() performs full receipt validation before any output is written.
    return summarize(records)


def _render_csv(summary: list[dict[str, Any]]) -> str:
    """Render the summary as CSV with LF record endings."""
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["customer", "count", "total"])
    for row in summary:
        writer.writerow([row["customer"], row["count"], row["total"]])
    return buffer.getvalue()


def _replace_output(path: str, content: str) -> None:
    """Atomically replace path with content, leaving it intact on failure."""
    directory = os.path.dirname(os.path.abspath(path))
    fd, temporary_path = tempfile.mkstemp(
        prefix=".receipt-summary-", suffix=".tmp", dir=directory
    )
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as target:
            target.write(content)
            target.flush()
            os.fsync(target.fileno())
        os.replace(temporary_path, path)
    except BaseException:
        try:
            os.unlink(temporary_path)
        except OSError:
            pass
        raise


def main(argv: Sequence[str] | None = None) -> int:
    """Run the CLI. Return a process exit status."""
    args = list(sys.argv[1:] if argv is None else argv)
    if len(args) != 2:
        print(
            "usage: python -m receipt_tools.cli INPUT.jsonl OUTPUT.csv",
            file=sys.stderr,
        )
        return 2

    input_path, output_path = args
    try:
        summary = _read_summary(input_path)
        content = _render_csv(summary)
    except Exception as exc:
        print(f"receipt_tools: {exc}", file=sys.stderr)
        return 1

    try:
        _replace_output(output_path, content)
    except Exception as exc:
        print(f"receipt_tools: cannot write output: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Validation and aggregation of receipt records."""

from __future__ import annotations

import re
from collections.abc import Iterable, Mapping
from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any

_AMOUNT_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?")
_CENT = Decimal("0.01")
_VALID_STATUSES = ("paid", "void")


def _require_text(record: Mapping[str, Any], field: str) -> str:
    """Return a required string field, or raise ValueError."""
    try:
        value = record[field]
    except (KeyError, TypeError, IndexError):
        raise ValueError(f"missing or invalid field: {field}") from None
    if not isinstance(value, str):
        raise ValueError(f"missing or invalid field: {field}")
    return value


def _validate_record(record: Any) -> tuple[str, Decimal, bool]:
    """Validate one receipt and return (customer, amount, is_paid)."""
    if not isinstance(record, Mapping):
        raise ValueError("receipt must be a mapping")

    customer = _require_text(record, "customer")
    amount_text = _require_text(record, "amount")
    status = _require_text(record, "status")

    customer = customer.strip()
    if not customer:
        raise ValueError("customer must be a nonempty string")

    if _AMOUNT_RE.fullmatch(amount_text) is None:
        raise ValueError("amount must be an ASCII decimal string")

    if status not in _VALID_STATUSES:
        raise ValueError('status must be "paid" or "void"')

    return customer, Decimal(amount_text), status == "paid"


def summarize(records: Iterable[Mapping[str, Any]]) -> list[dict[str, Any]]:
    """Summarize paid receipts per customer.

    Every record is validated regardless of status. Only paid records
    contribute to the count and total. Each customer total is rounded once,
    at the end, to two decimal places using ROUND_HALF_UP.
    """
    totals: dict[str, Decimal] = {}
    counts: dict[str, int] = {}

    # Keep ample precision while summing; no per-receipt rounding occurs.
    with localcontext() as ctx:
        ctx.prec = 100
        for record in records:
            customer, amount, is_paid = _validate_record(record)
            if is_paid:
                totals[customer] = totals.get(customer, Decimal(0)) + amount
                counts[customer] = counts.get(customer, 0) + 1

        result: list[dict[str, Any]] = []
        for customer in sorted(totals):
            rounded = totals[customer].quantize(_CENT, rounding=ROUND_HALF_UP)
            result.append(
                {
                    "customer": customer,
                    "count": counts[customer],
                    "total": str(rounded),
                }
            )

    return result

