"""Core receipt summarization logic."""

import re
from decimal import Decimal, ROUND_HALF_UP, localcontext

_AMOUNT_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?", re.ASCII)
_CENT = Decimal("0.01")
_ZERO = Decimal(0)
_PAID = "paid"
_VOID = "void"


def _field(record, name, index):
    try:
        return record[name]
    except KeyError:
        raise ValueError(
            "record {0}: missing required field {1!r}".format(index, name)
        ) from None
    except TypeError:
        raise ValueError(
            "record {0}: expected a mapping, got {1}".format(
                index, type(record).__name__
            )
        ) from None


def _customer(value, index):
    if not isinstance(value, str):
        raise ValueError(
            "record {0}: customer must be a string".format(index)
        )
    name = value.strip()
    if not name:
        raise ValueError(
            "record {0}: customer must be a nonempty string".format(index)
        )
    return name


def _amount(value, index):
    if not isinstance(value, str) or _AMOUNT_RE.fullmatch(value) is None:
        raise ValueError(
            "record {0}: amount must be a string matching "
            "[0-9]+(?:\\.[0-9]+)?".format(index)
        )
    return Decimal(value)


def _status(value, index):
    if not isinstance(value, str) or value not in (_PAID, _VOID):
        raise ValueError(
            "record {0}: status must be {1!r} or {2!r}".format(index, _PAID, _VOID)
        )
    return value


def summarize(records):
    """Summarize receipt records into sorted per-customer totals."""
    totals = {}
    counts = {}
    with localcontext() as ctx:
        ctx.prec = 60
        for index, record in enumerate(records):
            name = _customer(_field(record, "customer", index), index)
            amount = _amount(_field(record, "amount", index), index)
            status = _status(_field(record, "status", index), index)
            if status != _PAID:
                continue
            totals[name] = totals.get(name, _ZERO) + amount
            counts[name] = counts.get(name, 0) + 1
        summary = []
        for name in sorted(totals):
            total = totals[name].quantize(_CENT, rounding=ROUND_HALF_UP)
            summary.append(
                {"customer": name, "count": counts[name], "total": str(total)}
            )
    return summary
